(()=>{const key='portfolio-doodles-v1';let seed=fetch('/doodles-seed.json').then(r=>r.json()).catch(()=>[]);const read=()=>JSON.parse(localStorage.getItem(key)||'[]');const listeners=new Set();window.portfolioDoodles={from(){let asc=false,limit=200;const q={select(){return q},eq(){return q},order(k,o){asc=o?.ascending;return q},limit(n){limit=n;return q},async insert(row){try{const rows=read();rows.push({...row,id:crypto.randomUUID(),created_at:new Date().toISOString()});localStorage.setItem(key,JSON.stringify(rows));listeners.forEach(f=>f());return{error:null}}catch(error){return{error}}},then(resolve,reject){return seed.then(s=>({data:[...s,...read()].sort((a,b)=>(asc?1:-1)*a.created_at.localeCompare(b.created_at)).slice(0,limit),error:null})).then(resolve,reject)}};return q},channel(){let cb;const channel={on(a,b,c){cb=c;return channel},subscribe(){listeners.add(cb);return channel},close(){listeners.delete(cb)}};return channel},removeChannel(c){c.close()}}})();
